public static class Solution {
    public int[] productExceptSelf(int[] nums) {
        int n = nums.length;

        // Result array initialized with 1; this will store the final products.
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            result[i] = 1;
        }

        // Step 1: Calculate left products.
        // leftProduct stores the product of all elements to the left of index i.
        int leftProduct = 1;
        for (int i = 0; i < n; i++) {
            // result[i] currently holds the product of elements to the left of i.
            result[i] = leftProduct;
            // Update leftProduct to include the current element for the next iteration.
            leftProduct *= nums[i];
        }

        // Step 2: Calculate right products and multiply with left products.
        // rightProduct stores the product of all elements to the right of index i.
        int rightProduct = 1;
        for (int i = n - 1; i >= 0; i--) {
            // Multiply result[i] with the rightProduct to get the product of elements to the left and right of i.
            result[i] *= rightProduct;
            // Update rightProduct to include the current element for the next iteration.
            rightProduct *= nums[i];
        }

        // Result now contains the product of all elements except the element at each index.
        return result;
    }
}

