public static class Solution {
    /**
     * Function to find the maximum sum of a contiguous subarray using Kadane's Algorithm.
     * Kadane's Algorithm is a dynamic programming approach.
     *
     * @param nums The input array of integers.
     * @return The maximum sum of any contiguous subarray within the input array.
     */
    public int maxSubArray(int[] nums) {
        // Initialize maxSub with the first element of the array.
        // This ensures that if the array contains only negative numbers, the largest negative number is returned.
        int maxSub = nums[0];

        // Initialize curSum to 0. This variable will track the current subarray sum.
        int curSum = 0;

        // Iterate through each number in the array
        for (int n : nums) {
            // If the current sum becomes negative, reset it to 0.
            // A negative sum will only decrease the sum of a future subarray, so it's better to start a new subarray.
            if (curSum < 0) {
                curSum = 0;
            }

            // Add the current number to the current sum
            curSum += n;

            // Update maxSub with the maximum value between the current maxSub and curSum.
            // This ensures that maxSub always holds the maximum subarray sum encountered so far.
            maxSub = Math.max(maxSub, curSum);
        }

        // Return the maximum subarray sum
        return maxSub;
    }
}

