/**
 * Finds the maximum sum of a contiguous subarray.
 *
 * Uses Kadane's Algorithm.
 *
 * Core Idea:
 * - If the current subarray sum becomes negative, it will only
 *   reduce the sum of any future subarray.
 * - Therefore, we reset the current sum to 0 whenever it becomes negative.
 *
 * @param nums Vector of integers (can contain negative values)
 * @return Maximum subarray sum
 */
int maxSubArray(const vector<int>& nums) {

    // maxSub keeps track of the maximum subarray sum found so far.
    // Initialize with the first element to correctly handle
    // cases where all numbers are negative.
    int maxSub = nums[0];

    // curSum stores the sum of the current subarray.
    // It is reset whenever it becomes negative.
    int curSum = 0;

    // Iterate through each element in the array
    for (int n : nums) {

        // If current sum is negative, discard it.
        // A negative prefix will only reduce future sums.
        if (curSum < 0) {
            curSum = 0;
        }

        // Extend the current subarray by adding the current element
        curSum += n;

        // Update the maximum subarray sum seen so far
        maxSub = max(maxSub, curSum);
    }

    // Return the maximum subarray sum
    return maxSub;
}

