public static class Solution {
    public int maxProduct(int[] nums) {
        // Initialize maxProduct with the first element of the array.
        int maxProduct = nums[0];

        // Initialize currentMax and currentMin to track the maximum and minimum product ending at each index.
        int currentMax = nums[0];
        int currentMin = nums[0];

        // Iterate through the array starting from the second element.
        for (int i = 1; i < nums.length; i++) {
            int num = nums[i];

            // Store the currentMax to a temporary variable before updating it.
            // This is necessary because currentMax is used to calculate currentMin.
            int tempMax = currentMax;

            // Calculate the new currentMax.
            // It's the maximum of the current number, the current number multiplied by the previous currentMax,
            // and the current number multiplied by the previous currentMin.
            // We need to consider all three cases because the previous currentMin might become the maximum
            // when multiplied by a negative number.
            currentMax = Math.max(num, Math.max(num * currentMax, num * currentMin));

            // Calculate the new currentMin similarly.
            // It's the minimum of the current number, the current number multiplied by the previous tempMax,
            // and the current number multiplied by the previous currentMin.
            currentMin = Math.min(num, Math.min(num * tempMax, num * currentMin));

            // Update the global maxProduct with the maximum between the current maxProduct and the currentMax.
            maxProduct = Math.max(maxProduct, currentMax);
        }

        // After the loop finishes, return the global maximum product.
        return maxProduct;
    }
}

