public static class Solution {
    public int findMin(int[] nums) {
        // Initialize left and right pointers for binary search.
        int left = 0, right = nums.length - 1;

        // Handle edge case: empty array.
        if(nums.length == 0)
          return 0;

        // Binary search loop: continue until left and right pointers converge.
        while (left < right) {
            // Calculate the middle index to avoid potential overflow.
            int mid = left + (right - left) / 2;

            // If the middle element is greater than the rightmost element,
            // it means the minimum element is in the right half of the array.
            if (nums[mid] > nums[right]) {
                // Update the left pointer to search in the right half.
                left = mid + 1;
            } else {
                // Otherwise, the minimum element is in the left half (including the middle element).
                // Update the right pointer to search in the left half.
                right = mid;
            }
        }

        // When the loop finishes, the left pointer will be pointing to the minimum element.
        return nums[left];
    }
}

