public static class Solution {
    public int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1; // Initialize left and right pointers for binary search.

        while (left <= right) { // Continue searching while the left pointer is less than or equal to the right pointer.
            int mid = left + (right - left) / 2; // Calculate the middle index to avoid potential overflow.

            if (nums[mid] == target) { // If the middle element is the target, return the middle index.
                return mid;
            }

            // Determine which half is sorted
            if (nums[left] <= nums[mid]) { // Check if the left half is sorted.
                // Left half is sorted
                if (nums[left] <= target && target < nums[mid]) { // If the target is within the sorted left half.
                    right = mid - 1; // Move the right pointer to search in the left half.
                } else { // If the target is not in the sorted left half.
                    left = mid + 1; // Move the left pointer to search in the right half.
                }
            } else { // If the left half is not sorted, then the right half must be sorted.
                // Right half is sorted
                if (nums[mid] < target && target <= nums[right]) { // If the target is within the sorted right half.
                    left = mid + 1; // Move the left pointer to search in the right half.
                } else { // If the target is not in the sorted right half.
                    right = mid - 1; // Move the right pointer to search in the left half.
                }
            }
        }

        return -1; // If the target is not found, return -1.
    }
}

