    int[] ans = new int[n + 1];
    int offset = 1;
    for (int i = 1; i <= n; i++) {
        if (i == offset * 2) {
            offset = i;
        }
        ans[i] = 1 + ans[i - offset];
    }
    return ans;
}

cpp.raw:
vector<int> countBits(int n) {
    // ans[i] stores the number of set bits in i
    vector<int> ans(n + 1, 0);

    // offset tracks the current power of 2
    int offset = 1;

    // Start from 1 since ans[0] = 0
    for (int i = 1; i <= n; i++) {
        // Update offset when i reaches next power of 2
        if (i == offset * 2) {
            offset = i;
        }

        // DP formula:
        // ans[i] = 1 + ans[i - offset]
        ans[i] = 1 + ans[i - offset];
    }

    return ans;
}

